using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    // Add the default reflection-based resolver so metadata is
    // generated on-the-fly for any type we ask about.
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ── 1. Strongly-typed metadata retrieval ──────────────────────────
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"TypeInfo<Person> obtained – type handled: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

Person roundTripped = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {roundTripped}");

// ── 2. Probe without throwing ─────────────────────────────────────
// TryGetTypeInfo returns false instead of throwing when metadata
// isn't available.  We'll show both a hit and a miss.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"\nTryGetTypeInfo(Person) → found ({info!.Type.Name})");
else
    Console.WriteLine("\nTryGetTypeInfo(Person) → not found");

// Use an options instance with *no* resolver → nothing is resolvable.
var empty = new JsonSerializerOptions { TypeInfoResolver = null };
if (empty.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("TryGetTypeInfo on empty → found (unexpected!)");
else
    Console.WriteLine("TryGetTypeInfo on empty → not found (expected)");

// ── Types ─────────────────────────────────────────────────────────
record Person(string Name, int Age);

